import{z as d,x as p,o as r,c as A,q as o,j as s,D as n,d as t,s as i,S as E,b as e}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"集合覆盖贪心","description":"","frontmatter":{"title":"集合覆盖贪心","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/set-cover-greedy.md","filePath":"cs/set-cover-greedy.md","lastUpdated":1791413859000}'),B={name:"cs/set-cover-greedy.md"};function h(m,a,_,P,c,C){const l=p("Mermaid");return r(),A("div",null,[a[2]||(a[2]=o('<h1 id="集合覆盖贪心" tabindex="-1">集合覆盖贪心 <a class="header-anchor" href="#集合覆盖贪心" aria-label="Permalink to &quot;集合覆盖贪心&quot;">​</a></h1><div class="epigraph"><p>每次选覆盖新元素最多的集合，近似比 $H_n\\le \\ln n+1$；除非 P=NP 没有 $o(\\log n)$ 多项式近似。</p><footer>—— 据 Johnson, Approximation Algorithms for Combinatorial Problems, 1974；Chvátal, 1979；CLRS 第 35.3 节整理</footer></div><p>上一课<a href="/cs/vertex-cover-approx">顶点覆盖 2 近似</a>其实已是集合覆盖的特例——元素退化为边、集合退化为顶点的关联星时能压到 2。一般集合覆盖：宇宙 \\(n\\) 个元素、一个集合族，求最少的集合盖住全部。缺口是贪心的 \\(H_n\\) 比。本课不重写匹配；后课 Christofides TSP。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>贪心每次选覆盖新元素最多的集合。分析靠分摊记账：还剩 \\(k\\) 个未覆盖元素时，OPT 的集合平均每个盖住其中 \\(k/\\mathrm{OPT}\\) 个以上，按「每个新元素摊到的价钱」算，本次每元素代价 \\(\\le\\mathrm{OPT}/k\\)。剩余数一路下降，价钱逐级翻倍相加，恰是调和级数 \\(1+1/2+\\cdots+1/n=H_n\\le\\ln n+1\\)。加权版 Chvátal：改按性价比 \\(w(S)/\\text{新元素数}\\) 选，同一本账。</p><p>缺口是调和比 \\(H_n\\)，不是 2。</p><h3 id="顶点覆盖不是" tabindex="-1">顶点覆盖不是 \\(\\ln n\\) <a class="header-anchor" href="#顶点覆盖不是" aria-label="Permalink to &quot;顶点覆盖不是 $\\ln n$&quot;">​</a></h3><p>顶点覆盖虽是特例，却拿不到 \\(\\ln n\\)：一般贪心在那样的结构上仍可能差过 2，紧界要靠上一课的匹配下界。问题结构决定近似比，不是越一般越松。</p><p><span class="marginnote">Johnson 1974。Chvátal 加权。Feige $ (1-\\varepsilon)\\ln n $ 硬度。后课度量 TSP Christofides。</span></p><p><span class="marginnote">数字实例：\\(n=100\\) 时 \\(H_{100}\\approx 5.19\\)，即贪心解至多约是 OPT 的 5.2 倍——若最优解用 3 个集合，贪心至多约 16 个。不算好，但这是「不差于对数倍」的硬底线；且 Feige 硬度说明没有多项式算法能做得显著更好。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>实现：集合用倒排索引（元素指向包含它的集合），每步扫一遍找新覆盖最多的；已选集合惰性删除，总量级 \\(O(\\sum |S|)\\)。</p><p><span class="marginnote">术语翻译：「倒排索引」就是不从集合找元素、反过来从元素查集合——像书后的关键词索引：想覆盖某个元素，先查它出现在哪些集合里，再挑性价比最高的，省掉每轮把所有集合全扫一遍的浪费。</span></p>',13)),(r(),s(E,null,{default:n(()=>[i(l,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20U%5B%22%E6%9C%AA%E8%A6%86%E7%9B%96%22%5D%20--%3E%20GRD%5B%22%E9%80%89%E6%80%A7%E4%BB%B7%E6%AF%94%E6%9C%80%E5%A4%A7%22%5D%0A%20%20GRD%20--%3E%20HN%5B%22%E6%AF%94%20%E2%89%A4%20H_n%22%5D%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"\\(n\\) 小到几十时可状压精确求解，指数换最优。",-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[t("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"机制就是分摊论证：OPT 的某集合总盖住剩余的至少 \\(1/\\mathrm{OPT}\\) 比例，贪心不差于这个「平均」，每元素摊价随剩余减少而几何上升，调和级数由此而来。它与子模函数最大化的贪心同族——覆盖函数是典型子模，「新元素」计数的理由正是边际收益递减。LP 视角：整数规划的对偶是 packing，对偶拟合同样给出 \\(H_n\\)，两条路殊途同归。",-1)),a[6]||(a[6]=e("p",null,"上面那张图是贪心的选择动作；下面这张把分摊论证画成循环——\\(H_n\\) 就是这个循环里逐级上升的摊价之和。",-1)),(r(),s(E,null,{default:n(()=>[i(l,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E5%89%A9%E4%BD%99%20k%20%E4%B8%AA%E6%9C%AA%E8%A6%86%E7%9B%96%22%5D%20--%3E%20B%5B%22OPT%20%E6%9F%90%E9%9B%86%E5%90%88%E5%B9%B3%E5%9D%87%E7%9B%96%20k%2FOPT%20%E4%B8%AA%22%5D%0A%20%20B%20--%3E%20C%5B%22%E6%9C%AC%E6%AC%A1%E6%AF%8F%E6%96%B0%E5%85%83%E7%B4%A0%E6%91%8A%E4%BB%B7%20%E2%89%A4%20OPT%2Fk%22%5D%0A%20%20C%20--%3E%20D%5B%22%E6%89%A3%E6%8E%89%E8%BF%99%E6%89%B9%20k%20%E5%8F%98%E5%B0%8F%22%5D%0A%20%20D%20--%3E%20E%7B%22%E8%BF%98%E6%9C%89%E6%9C%AA%E8%A6%86%E7%9B%96%3F%22%7D%0A%20%20E%20--%20%22%E6%98%AF%22%20--%3E%20A%0A%20%20E%20--%20%22%E5%90%A6%22%20--%3E%20F%5B%22%E6%80%BB%E4%BB%A3%E4%BB%B7%20%E2%89%A4%20OPT%20%C3%97%20(1%20%2B%201%2F2%20%2B%20%E2%80%A6%20%2B%201%2Fn)%20%3D%20OPT%C2%B7H_n%22%5D%0A"})]),fallback:n(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=o('<p><span class="marginnote">直觉类比：分摊记账像买散装货——剩得越多平均每件越便宜，剩得越少平均每件越贵；把每个「层次」的贵价按 \\(1, 1/2, 1/3,\\dots\\) 加总，正好是调和级数，这就是 \\(H_n\\) 的来处。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不证 Feige 硬度，只点名结论：\\((1-\\varepsilon)\\ln n\\) 以内的近似即推出 P=NP——对数比是本质的，不是分析不紧。不写带罚金的部分覆盖变体。后课默认：集合覆盖贪心 \\(H_n\\)。下一课 Christofides。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>贪心性价比，\\(H_n\\)-近似。</li><li>对数比本质（硬度）。</li><li>特殊图结构可用更紧算法。</li><li>出处：Johnson, 1974；Chvátal, 1979；CLRS 第 35.3 节。</li></ul>',5))])}const u=d(B,[["render",h]]);export{f as __pageData,u as default};
